//go:build stream

package stream

import (
	"bufio"
	"bytes"
	"encoding/hex"
	"io"
	"net"
	"sync"
	"testing"
	"time"
)

// Typical-size padded ClientHello, SNI shared.example, offers h2 and http/1.1.
func phase0Hello() []byte {
	wire, err := hex.DecodeString("")
	if err != nil {
		panic(err)
	}
	return wire
}

func phase0Inspect(br *bufio.Reader) { _ = peekClientHello(br, true) }

func BenchmarkALPNPhase0Parser(b *testing.B) {
	wire := phase0Hello()
	reader := bytes.NewReader(wire)
	br := bufio.NewReaderSize(reader, tlsInspectMax)
	b.ReportAllocs()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		reader.Reset(wire)
		br.Reset(reader)
		phase0Inspect(br)
	}
}

// Measures a fresh TCP connection, ClientHello preread, backend dial and full
// ClientHello echo. This includes establishment work; it excludes TLS crypto.
func BenchmarkALPNPhase0Connection(b *testing.B) {
	backend, stopBackend := benchBackend()
	defer stopBackend()
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		b.Fatal(err)
	}
	var workers sync.WaitGroup
	acceptDone := make(chan struct{})
	go func() {
		defer close(acceptDone)
		for {
			client, err := ln.Accept()
			if err != nil {
				return
			}
			workers.Add(1)
			go func() {
				defer workers.Done()
				defer client.Close()
				_ = client.SetDeadline(time.Now().Add(5 * time.Second))
				br := bufio.NewReaderSize(client, tlsInspectMax)
				phase0Inspect(br)
				upstream, err := net.DialTimeout("tcp", backend, 5*time.Second)
				if err != nil {
					return
				}
				defer upstream.Close()
				_ = upstream.SetDeadline(time.Now().Add(5 * time.Second))
				done := make(chan struct{})
				go func() { _, _ = io.Copy(upstream, br); _ = upstream.Close(); close(done) }()
				_, _ = io.Copy(client, upstream)
				_ = client.Close()
				<-done
			}()
		}
	}()
	defer func() { _ = ln.Close(); <-acceptDone; workers.Wait() }()
	wire := phase0Hello()
	reply := make([]byte, len(wire))
	b.ReportAllocs()
	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		client, err := net.DialTimeout("tcp", ln.Addr().String(), 5*time.Second)
		if err != nil {
			b.Fatal(err)
		}
		_ = client.SetDeadline(time.Now().Add(5 * time.Second))
		if _, err = client.Write(wire); err != nil {
			_ = client.Close()
			b.Fatal(err)
		}
		_, err = io.ReadFull(client, reply)
		_ = client.Close()
		if err != nil || !bytes.Equal(reply, wire) {
			b.Fatalf("replay: %v", err)
		}
	}
	b.StopTimer()
}
